  "components": {
    "schemas": {
      "RaitCase": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string",
            "format": "uuid",
            "default": "gen_random_uuid()"
          },
          "tenant_id": {
            "type": "string",
            "format": "uuid"
          },
          "ait_id": {
            "type": "string",
            "format": "uuid"
          },
          "origin_case_id": {
            "type": "string",
            "format": "uuid",
            "nullable": true
          },
          "protocol_number": {
            "type": "string",
            "maxLength": 40
          },
          "instance": {
            "type": "string",
            "maxLength": 20,
            "enum": ["defesa_previa", "jari", "cetran"]
          },
          "circuit": {
            "type": "integer"
          },
          "state": {
            "type": "string",
            "maxLength": 40,
            "enum": [
              "PROTOCOLADO",
              "TRIAGEM_ADMISSIBILIDADE",
              "NAO_CONHECIDO",
              "ADMITIDO",
              "AGUARDANDO_REMESSA_JARI",
              "DISTRIBUIDO",
              "EM_INSTRUCAO",
              "DILIGENCIA",
              "PRONTO_P_DECISAO",
              "DECIDIDO_AUTORIDADE",
              "PAUTADO",
              "JULGADO_SESSAO",
              "COMUNICADO",
              "TRANSITADO",
              "REMETIDO_2A_INSTANCIA",
              "ENCERRADO_DESISTENCIA"
            ],
            "default": "'PROTOCOLADO'"
          },
          "intake_channel": {
            "type": "string",
            "maxLength": 30
          },
          "protocolled_at": {
            "type": "string",
            "format": "date-time"
          },
          "admitted_at": {
            "type": "string",
            "format": "date-time",
            "nullable": true
          },
          "judge_body_received_at": {
            "type": "string",
            "format": "date-time",
            "nullable": true
          },
          "judge_body_received_on": {
            "type": "string",
            "format": "date",
            "nullable": true
          },
          "cetran_received_at": {
            "type": "string",
            "format": "date-time",
            "nullable": true
          },
          "cetran_received_on": {
            "type": "string",
            "format": "date",
            "nullable": true
          },
          "remitted_at": {
            "type": "string",
            "format": "date-time",
            "nullable": true
          },
          "decided_at": {
            "type": "string",
            "format": "date-time",
            "nullable": true
          },
          "communicated_at": {
            "type": "string",
            "format": "date-time",
            "nullable": true
          },
          "closed_at": {
            "type": "string",
            "format": "date-time",
            "nullable": true
          },
          "suspensive_effect": {
            "type": "boolean",
            "default": "false"
          },
          "archived": {
            "type": "boolean",
            "default": "false"
          },
          "non_admission_reason": {
            "type": "string",
            "maxLength": 40,
            "enum": [
              "intempestivo",
              "ilegitimo",
              "sem_assinatura",
              "pedido_incompativel"
            ],
            "nullable": true
          },
          "withdrawal_document_id": {
            "type": "string",
            "format": "uuid",
            "nullable": true
          },
          "last_movement_at": {
            "type": "string",
            "format": "date-time",
            "default": "now()"
          },
          "pending_completion": {
            "type": "boolean",
            "default": "false"
          },
          "legal_priority": {
            "type": "string",
            "maxLength": 30,
            "nullable": true
          },
          "unit_id": {
            "type": "string",
            "format": "uuid",
            "nullable": true
          },
          "agency_jurisdiction_id": {
            "type": "string",
            "format": "uuid",
            "nullable": true
          },
          "version": {
            "type": "integer",
            "default": "1"
          },
          "created_at": {
            "type": "string",
            "format": "date-time"
          },
          "updated_at": {
            "type": "string",
            "format": "date-time",
            "nullable": true
          }
        },
        "required": [
          "tenant_id",
          "ait_id",
          "protocol_number",
          "instance",
          "circuit",
          "intake_channel",
          "protocolled_at",
          "created_at"
        ],
        "description": "Caso RAIT — um requerimento sobre um AIT em uma instancia (RN-RAIT-002). v1.1.0: legal_priority guarda a base de prioridade legal de tramitacao da ordem unica (WF-RAIT-004 secao 2; valores no parametro rait.priority.legal_bases, OD-016 — sem check para nao congelar parametro em DDL), unit_id aponta a turma/JARI que julga (secao 7, sem FK: inf.rait_unit nasce no DDL 35, posterior ao 34) e version e o contador de ETag/If-Match."
